const names = [
  // старый ИТ-список
  'Typeform','Wallapop','TravelPerk','Genially','Red Points','Copado','Freepik','Badi','Holded','Jobandtalent','Seedtag','Sherpa.ai','Clarity AI','Manychat','Housfy','Wallbox','Flanks','Fever','Cabify','Domestika','Idealista','Multiverse Computing','Devo','Signaturit','Chicfy','Deporvillage','Job Today','Datumize','Bipi','Alice Biometrics','Zeleros','Divilo',
  // новое — не-ИТ: BPO/CX, доставка/логистика, travel, mobility, fintech-consumer, media
  'Glovo','Wolt','Deliveroo','eDreams ODIGEO','Adevinta','Cooltra','Rakuten TV','HelloFresh','Fintonic','Bnext','Younited Credit','Uber','Booking','Trivago','SEUR','GLS Spain'
];
const out = [];
for (const name of names) {
  const base = name.toLowerCase().replace(/[^a-z0-9]/g, '');
  const kebab = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const candidates = new Set([base, base + 'hr', base + 'app', base + 'spain', kebab]);
  for (const slug of candidates) {
    if (slug) out.push({ json: { name, slug } });
  }
}
return out;

const atsTypes = [
  { ats_type: 'greenhouse', urlTpl: slug => `https://boards-api.greenhouse.io/v1/boards/${slug}/jobs` },
  { ats_type: 'greenhouse_eu', urlTpl: slug => `https://boards-api.eu.greenhouse.io/v1/boards/${slug}/jobs` },
  { ats_type: 'lever', urlTpl: slug => `https://api.lever.co/v0/postings/${slug}?mode=json` },
  { ats_type: 'ashby', urlTpl: slug => `https://api.ashbyhq.com/posting-api/job-board/${slug}` },
  { ats_type: 'smartrecruiters', urlTpl: slug => `https://api.smartrecruiters.com/v1/companies/${slug}/postings` },
  { ats_type: 'workable', urlTpl: slug => `https://apply.workable.com/api/v1/widget/accounts/${slug}` }
];
const out = [];
for (const item of $input.all()) {
  for (const ats of atsTypes) {
    out.push({ json: {
      name: item.json.name,
      slug: item.json.slug,
      ats_type: ats.ats_type,
      url: ats.urlTpl(item.json.slug)
    } });
  }
}
return out;

const origItems = $('Expand to ATS candidates').all();
const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const input = $input.all()[i];
  const orig = origItems[i].json;
  const status = input.json.statusCode;
  let body = input.json.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = null; }
  }
  let ok = false;
  if (status === 200 && body) {
    if ((orig.ats_type === 'greenhouse' || orig.ats_type === 'greenhouse_eu') && Array.isArray(body.jobs) && body.jobs.length > 0) ok = true;
    if (orig.ats_type === 'lever' && Array.isArray(body) && body.length > 0) ok = true;
    if (orig.ats_type === 'ashby' && Array.isArray(body.jobs) && body.jobs.length > 0) ok = true;
    if (orig.ats_type === 'smartrecruiters' && Array.isArray(body.content) && body.content.length > 0) ok = true;
    if (orig.ats_type === 'workable' && Array.isArray(body.jobs) && body.jobs.length > 0) ok = true;
  }
  if (ok) {
    results.push({ json: { name: orig.name, slug: orig.slug, ats_type: orig.ats_type } });
  }
}

return results;
